'use strict';
let workspaceView='medicaments';
function showView(view){workspaceView=view;$('#detail').hidden=view==='catalogue'||view==='document';$('#catalogue').hidden=view!=='catalogue';$('#document-reader').hidden=view!=='document';document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});if(view==='catalogue')renderCatalogue();if(view==='document')renderDocument(selected.page)}
function renderCatalogue(){const root=$('#catalogue');root.replaceChildren();root.append(el('div','eyebrow','INTÉGRALITÉ DU LIVRET FOURNI'),el('h2','','Tous les médicaments'),el('p','catalogue-intro',DOCUMENT.medicine_count+' médicaments · '+DOCUMENT.checklist_count+' checklists : '+DOCUMENT.adult_count+' adultes et '+DOCUMENT.pediatric_count+' pédiatriques. Les pages de tableaux et de contre-indications de suite sont rattachées à leur fiche. Les 8 repères généraux se trouvent dans l’onglet dédié.'));const grid=el('div','catalogue-grid'),groups=new Map;for(const f of MEDICATIONS){if(!groups.has(f.medicine))groups.set(f.medicine,[]);groups.get(f.medicine).push(f)}for(const[name,rows]of [...groups].sort((a,b)=>a[0].localeCompare(b[0],'fr'))){const card=el('article','medicine-group');card.append(el('h3','',name),el('p','muted',rows.length+' checklist'+(rows.length>1?'s':'')));for(const f of rows){const b=el('button','',(f.population==='adulte'?'Adulte':'Pédiatrie')+' · '+(f.context||f.sections.indication[0]?.text||f.title)+' · p. '+f.page);b.onclick=()=>{population='tous';$('#search').value='';onlyFavorites=false;$('#favorites').classList.remove('active');$('#favorites').setAttribute('aria-pressed',false);select(f)};card.append(b)}grid.append(card)}root.append(grid,el('p','doc-notice','Relecture de la transcription et contrôles techniques effectués. Validation clinique de l’adaptation non effectuée. Les listes médicales restent celles du livret et ne sont pas exhaustives, comme le précise sa page 16.'))}
function renderDocument(initial){const root=$('#document-reader');root.replaceChildren();root.append(el('div','eyebrow','DOCUMENT SOURCE COMPLET'),el('h2','','Les 106 pages du PDF'),el('p','catalogue-intro','Toutes les pages sont accessibles : préface, sommaires, repères, médicaments, tableaux et références. Les pages administratives et les pages blanches restent des annexes ; elles ne sont pas transformées en actions cliniques.'));const controls=el('div','doc-controls'),prev=el('button','','←'),next=el('button','','→'),selectPage=el('select');selectPage.id='document-page';selectPage.setAttribute('aria-label','Choisir une page du document');for(const p of DOCUMENT.pages){const o=el('option','',p.page+' · '+p.title);o.value=p.page;selectPage.append(o)}const open=el('button','','Ouvrir la checklist associée'),link=pdfLink(initial,'Page PDF ↗'),title=el('h3'),image=el('img','doc-page-image');image.loading='lazy';const status=el('p','muted');let current=Math.min(DOCUMENT.page_count,Math.max(1,Number(initial)||1));function change(n){current=n;const p=DOCUMENT.pages[n-1];selectPage.value=String(n);title.textContent='Page '+n+' · '+p.title;image.src='assets/page-'+n+'.jpg';image.alt='Page originale '+n+' du livret — '+p.title;link.href=pdfTarget(n);open.disabled=!p.target;open.onclick=()=>{const f=FICHES.find(f=>f.page===p.target);if(f){population=f.category==='guide'?'reperes':'tous';$('#search').value='';onlyFavorites=false;$('#favorites').classList.remove('active');$('#favorites').setAttribute('aria-pressed',false);select(f)}};status.textContent=p.kind==='reference'?'Page de référence du document, conservée en annexe.':'Contenu disponible en checklist interactive, avec la source en annexe.';prev.disabled=n<=1;next.disabled=n>=DOCUMENT.page_count}selectPage.onchange=()=>change(Number(selectPage.value));prev.onclick=()=>change(current-1);next.onclick=()=>change(current+1);controls.append(prev,selectPage,next,link,open);root.append(controls,status,title,image);change(current)}
function initLibrary(){$('#coverage').textContent=DOCUMENT.medicine_count+' médicaments · '+DOCUMENT.checklist_count+' checklists · '+DOCUMENT.guide_count+' repères · '+DOCUMENT.page_count+' pages';document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const v=b.dataset.view;if(v==='catalogue'||v==='document'){showView(v);return}population=v==='reperes'?'reperes':'tous';$('#search').value='';onlyFavorites=false;$('#favorites').classList.remove('active');$('#favorites').setAttribute('aria-pressed',false);const f=v==='reperes'?GUIDES[0]:(selected.category==='medicament'?selected:MEDICATIONS[0]);select(f)});}
